CREATE DATABASE IF NOT EXISTS student_admission_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE student_admission_db;
CREATE TABLE IF NOT EXISTS admissions (id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(150) NOT NULL,father_name VARCHAR(150) NOT NULL,dob DATE NOT NULL,gender VARCHAR(15) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(25) NOT NULL,cnic VARCHAR(20) NOT NULL,address TEXT NOT NULL,qualification VARCHAR(150) NOT NULL,course VARCHAR(100) NOT NULL,admission_date DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inquiries (id INT AUTO_INCREMENT PRIMARY KEY,student_name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(25) NOT NULL,subject VARCHAR(200) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admins (id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
